const SvgTextAnnotationItem  = ({ item, index, idKey }) => {
	const [visible, setVisible] = useState(true);
	const [obs, set_obs] = useState(1);
	const {description, boundingPoly} = item;

	let vert = boundingPoly?.vertices;
	

	let hh =  vert?.[3]?.y - vert?.[0]?.y;
	let ww =  vert?.[1]?.x - vert?.[0]?.x ;


	const handleVisible = (e) =>{
		e.stopPropagation();
		e.preventDefault();
		
	}

	const handleCm = (e) =>{
		e.stopPropagation();
		e.preventDefault();
		
	}

	if(index === 0 || !vert?.[1]){
		return null;
	}



	return (
		<rect
			onClick={handleVisible}
			onContextMenu={handleCm}
			width={ww} 
			height={hh}
			fill={"#646cff"}
			fill-opacity="50%"
			x={vert?.[0]?.x }
			y={vert?.[0]?.y} 
		/>
	)

}


































